import { camera, createAuraApp, lights, material, primitives, scene } from "@aura3d/engine";

// uTime is reserved by the shader prelude, so use our own uniform driven from app.onFrame.
const pulse = material.custom({
  glsl: {
    fragment: /* glsl */ `
out vec4 outColor;
void main() { outColor = vec4(0.9, 0.3 + 0.5 * sin(pulseClock), 0.3, 1.0); }`
  },
  uniforms: { pulseClock: { type: "f32", value: 0 } }
});

async function main(): Promise<void> {
  const app = createAuraApp("#app", {
  scene: scene({ background: "#1b2230" })
    .add(lights.directional({ position: [4, 6, 3], intensity: 2.5 }))
    .add(
      primitives
        .sphere({ name: "pulse", material: pulse })
        .position(0, 0.8, 0)
        .scale(2)
        .runtime({ id: "pulse", mutable: true })
    )
    .camera(camera.orbit({ target: [0, 0.5, 0], distance: 8, fov: 40 }))
});
  await app.ready();
  const start = performance.now();
  app.onFrame(() => {
    const seconds = (performance.now() - start) / 1000;
    app.nodes.require("pulse").setUniform?.("pulseClock", seconds);
  });
}
void main();
